begin;
do $$
declare a uuid:=gen_random_uuid();j jsonb;r jsonb;op jsonb;oldlease uuid;oldrevision bigint;
 state jsonb:='{"status":"resetting","available_count":2,"checked_at":"2026-10-15T00:00:00Z","attempt_cycle_hash":"aaaaaaaaaaaaaaaaaaaaaaaa","attempt_credit_hash":"bbbbbbbbbbbbbbbbbbbbbbbb"}';
begin
 insert into public.s2a_accounts(id,name,account_fingerprint,ciphertext,iv,extra) values(a,'Auto reset','auto-reset-db','cipher','iv','{"privacy_mode":"training_off"}');
 if exists(select 1 from public.s2a_openai_auto_reset_jobs where account_id=a) then raise exception 'auto reset enabled by default';end if;
 update public.s2a_accounts set extra=extra||'{"auto_reset_credit_enabled":true}' where id=a;
 if (select extra->>'auto_reset_credit_5h_threshold' from public.s2a_accounts where id=a)<>'1' then raise exception 'default threshold missing';end if;
 begin update public.s2a_accounts set extra=extra||'{"auto_reset_credit_5h_threshold":0}' where id=a;raise exception 'accepted_zero_threshold';exception when others then if sqlerrm<>'invalid_auto_reset_threshold' then raise;end if;end;
 begin update public.s2a_accounts set type='apikey' where id=a;raise exception 'accepted_api_key';exception when others then if sqlerrm<>'invalid_auto_reset_account' then raise;end if;end;
 j:=public.s2a_openai_auto_reset_claim()->0;
 if j->>'account_id'<>a::text then raise exception 'enabled account not claimed';end if;
 oldlease:=(j->>'lease_id')::uuid;oldrevision:=(j->>'revision')::bigint;
 if public.s2a_openai_auto_reset_claim()<>'[]'::jsonb then raise exception 'live lease claimed twice';end if;
 if public.s2a_openai_auto_reset_state(a,oldrevision,gen_random_uuid(),state) then raise exception 'foreign worker wrote state';end if;
 if not public.s2a_openai_auto_reset_state(a,oldrevision,oldlease,state) then raise exception 'state save rejected';end if;
 update public.s2a_accounts set extra=extra-'codex_auto_reset_credit_state' where id=a;
 if (select extra->'codex_auto_reset_credit_state' from public.s2a_accounts where id=a)<>state then raise exception 'edit erased saved attempt';end if;
 op:=public.s2a_openai_quota_reset_begin(a,null,'auto-key',1,'original-private-credit',oldrevision,oldlease);
 if not op?'id' then raise exception 'target reset not acquired: %',op;end if;
 r:=public.s2a_openai_quota_reset_begin(a,null,'manual-key',1);
 if r->>'error'<>'quota_reset_target_conflict' then raise exception 'manual request joined target reset';end if;
 update public.s2a_accounts set extra=extra||'{"auto_reset_credit_5h_threshold":0.5}' where id=a;
 if public.s2a_openai_quota_reset_dispatch((op->>'id')::uuid,(op->>'lease_id')::uuid) then raise exception 'config change did not fence dispatch';end if;
 if public.s2a_openai_auto_reset_finish(a,oldrevision,oldlease,state,60) then raise exception 'stale revision finished';end if;
 j:=public.s2a_openai_auto_reset_claim()->0;
 if (j->>'revision')::bigint<=oldrevision then raise exception 'config did not increment revision';end if;
 update public.s2a_openai_quota_resets set lease_until=now()-interval '1 second' where id=(op->>'id')::uuid;
 r:=public.s2a_openai_quota_reset_begin(a,null,'auto-retry',1,'replacement-credit',(j->>'revision')::bigint,(j->>'lease_id')::uuid);
 if r->>'error'<>'quota_reset_target_conflict' then raise exception 'pending reset changed card';end if;
 r:=public.s2a_openai_auto_reset_pending(a);
 if r->>'credit_id'<>'original-private-credit' or r->>'key'<>'auto-key' then raise exception 'pending target identity lost';end if;
 r:=public.s2a_openai_quota_reset_begin(a,null,'auto-key',1,'original-private-credit',(j->>'revision')::bigint,(j->>'lease_id')::uuid);
 if r->>'id'<>op->>'id' then raise exception 'retry changed redemption id';end if;
 if not public.s2a_openai_quota_reset_dispatch((r->>'id')::uuid,(r->>'lease_id')::uuid) then raise exception 'reclaimed worker cannot dispatch';end if;
 update public.s2a_accounts set extra=extra||'{"auto_reset_credit_enabled":false}' where id=a;
 if exists(select 1 from public.s2a_openai_auto_reset_jobs where account_id=a) then raise exception 'disabled account remains queued';end if;
 if public.s2a_openai_quota_reset_dispatch((r->>'id')::uuid,(r->>'lease_id')::uuid) then raise exception 'disabled account dispatched';end if;
 if not public.s2a_openai_quota_reset_consumed((r->>'id')::uuid,(r->>'lease_id')::uuid,'{"code":"success","windows_reset":1}') then raise exception 'late receipt lost after disable';end if;
 update public.s2a_accounts set extra=extra||'{"auto_reset_credit_enabled":true}' where id=a;
 j:=public.s2a_openai_auto_reset_claim()->0;
 state:=state||'{"status":"success","last_result_at":"2026-10-15T00:00:00Z"}';
 if not public.s2a_openai_auto_reset_finish(a,(j->>'revision')::bigint,(j->>'lease_id')::uuid,state,60) then raise exception 'current worker cannot finish';end if;
 if not exists(select 1 from public.s2a_openai_auto_reset_jobs where account_id=a and lease_id is null and next_attempt_at>now()) then raise exception 'finish did not schedule next check';end if;
 if not exists(select 1 from public.s2a_audit_logs where action='system.openai.reset_credit.auto' and extra->>'account_id'=a::text and extra->>'result_code'='success') then raise exception 'automatic reset audit missing';end if;
 begin perform public.s2a_openai_auto_reset_state(a,1,gen_random_uuid(),state||'{"credit_id":"private"}');raise exception 'accepted_secret_state';exception when others then if sqlerrm<>'invalid_auto_reset_state' then raise;end if;end;
 if has_table_privilege('service_role','public.s2a_openai_auto_reset_jobs','select') or has_function_privilege('authenticated','public.s2a_openai_auto_reset_pending(uuid)','execute')
  or has_function_privilege('anon','public.s2a_openai_auto_reset_claim()','execute') then raise exception 'private auto reset data exposed';end if;
end $$;
rollback;
